Formula (Emission):
IF(@ISMBR("Calculated") )
     "Scope 1 Usage"->"Total ESG Trace" * "Scope 1 Renewable %"->"CO2e (kG/kWh)" ;
ENDIF

IF(@ISMBR("Calculated") )
     "Scope 2 Location Based Emissions"->"Total ESG Trace" * "Scope 2 Location Based Renewable %"->"CO2e (kG/kWh)" ;
ENDIF

IF(@ISMBR("Calculated") )
     "Scope 2 Market Based Emissions"->"Total ESG Trace" * "Scope 2 Market Based Renewable %"->"CO2e (kG/kWh)";
ENDIF

Formula:
/* (Total energy consumption related to own operations/ Net Revenue) */
IF(@ISMBR("Kwh"))
	"ESRS E1-5.25"/ "ESRS 2- SBM-1.40b"->"EUR";
ELSEIF(@ISMBR("Mwh"))
	"ESRS E1-5.25"/ "ESRS 2- SBM-1.40b"->"EUR";
ENDIF

/* 15c Water Withdrawal (W) - 15d Water Discharge (D) */
















IF(@ISMBR("m3"))
	IF(@ISMBR("FY25"))
    	"ESRS E3-E4_28a";
    ELSE
      /*"ESRS E3-E4_28a"/ "ESRS 2- SBM-1.40b"->"EUR";*/
